INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass jedes Netzwerkprotokoll immer alle Ebenen eines Modells nutzt?', 2, '[{"text": "Nein", "correct": true, "because": "Protokolle decken oft nur bestimmte Ebenen ab"}, {"text": "Ja", "correct": false, "because": "Nicht alle Ebenen immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ebene des OSI-Modells ist für die Datenweiterleitung zwischen Netzen zuständig?', 3, '[{"text": "Schicht 3", "correct": true, "because": "Netzwerkschicht für Routing"}, {"text": "Schicht 2", "correct": false, "because": "Für lokale Übertragung"}, {"text": "Schicht 7", "correct": false, "because": "Anwendungsschicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle sind typisch für die Transportschicht?', 5, '[{"text": "TCP", "correct": true, "because": "Zuverlässige Übertragung"}, {"text": "UDP", "correct": true, "because": "Schnelle Übertragung"}, {"text": "HTTP", "correct": false, "because": "Anwendungsschicht"}, {"text": "FTP", "correct": false, "because": "Anwendungsschicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das OSI-Modell hat sieben Ebenen. b) Es wird immer vollständig implementiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft teilweise genutzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Analyse eines Netzwerkprotokolls?', 4, '[{"text": "Schichtzuordnung", "correct": false, "because": "Definiert Funktion"}, {"text": "Datenformat", "correct": false, "because": "Bestimmt Struktur"}, {"text": "Protokollfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das TCP/IP-Modell weniger Ebenen als das OSI-Modell hat?', 2, '[{"text": "Ja", "correct": true, "because": "Vier statt sieben Ebenen"}, {"text": "Nein", "correct": false, "because": "TCP/IP ist kompakter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schicht sorgt für die physische Verbindung?', 4, '[{"text": "Schicht 1", "correct": true, "because": "Physische Schicht für Hardware"}, {"text": "Schicht 4", "correct": false, "because": "Transportschicht"}, {"text": "Schicht 6", "correct": false, "because": "Präsentationsschicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Anwendungsschicht nur für HTTP zuständig ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch FTP, SMTP, mehr"}, {"text": "Ja", "correct": false, "because": "Mehrere Protokolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Sicherungsschicht für Routing zuständig?', 2, '[{"text": "Nein", "correct": true, "because": "Schicht 2 für lokale Übertragung"}, {"text": "Ja", "correct": false, "because": "Routing ist Schicht 3"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernehmen die unteren Ebenen?', 5, '[{"text": "Physische Übertragung", "correct": true, "because": "Schicht 1 für Hardware"}, {"text": "Fehlererkennung", "correct": true, "because": "Schicht 2 für Frames"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Höhere Ebenen"}, {"text": "Anwendungslogik", "correct": false, "because": "Schicht 7"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Fehlersuche in einem Netzwerk?', 4, '[{"text": "Schichtweise Analyse", "correct": true, "because": "Isoliert Problem"}, {"text": "Zufällige Tests", "correct": false, "because": "Ineffizient"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) TCP/IP kombiniert Schichten. b) Es ist identisch mit OSI.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, andere Struktur"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein Protokoll zu verstehen?', 3, '[{"text": "Schichtzuordnung", "correct": false, "because": "Definiert Funktion"}, {"text": "Datenfluss", "correct": false, "because": "Zeigt Interaktion"}, {"text": "Protokollnummer", "correct": true, "because": "Kein Verständnisfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich ein Verbindungsproblem analysiere?', 4, '[{"text": "Von Schicht 1 aufwärts prüfen", "correct": true, "because": "Systematischer Ansatz"}, {"text": "Nur Anwendung prüfen", "correct": false, "because": "Ignoriert untere Ebenen"}, {"text": "Zufällig starten", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Sicherungsschicht für IP-Adressen zuständig ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "IP-Adressen sind Schicht 3"}, {"text": "Ja", "correct": false, "because": "Schicht 2 nutzt MAC-Adressen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll arbeitet auf der Anwendungsschicht?', 4, '[{"text": "HTTP", "correct": true, "because": "Für Webanwendungen"}, {"text": "IP", "correct": false, "because": "Netzwerkschicht"}, {"text": "ARP", "correct": false, "because": "Sicherungsschicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat das OSI-Modell vier Ebenen?', 2, '[{"text": "Nein", "correct": true, "because": "Sieben Ebenen"}, {"text": "Ja", "correct": false, "because": "Vier sind TCP/IP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Schichtenmodell?', 5, '[{"text": "Modularität", "correct": true, "because": "Ermöglicht Austausch"}, {"text": "Fehlerisolierung", "correct": true, "because": "Schichtweise Analyse"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Modellvorteil"}, {"text": "Bunte Darstellung", "correct": false, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Analyse eines Modells unwichtig?', 3, '[{"text": "Schichtaufgaben", "correct": false, "because": "Definieren Funktion"}, {"text": "Protokollzuordnung", "correct": false, "because": "Bestimmt Interaktion"}, {"text": "Modellfarben", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich ein neues Protokoll entwickle?', 4, '[{"text": "Schicht definieren und Standards beachten", "correct": true, "because": "Sichert Kompatibilität"}, {"text": "Nur Datenformat wählen", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Schicht arbeiten", "correct": false, "because": "Unstrukturiert"}]');
